selected.compute:
options = read('/input/options')
result = []
for k in range(2, 4):
    for group in combinations(options, k):
        ids = [item['id'] for item in group]
        if valid(ids):
            ordered = sorted(group, key=lambda item: (item['rank'], item['id']))
            result = [item['id'] for item in ordered]
            break
    if len(result) > 0:
        break

selected.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if valid(current):
        result = current
    else:
        result = []
else:
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
